import{_ as e,o as a,c as d,a5 as r}from"./chunks/framework.D_J2JZBr.js";const g=JSON.parse('{"title":"IC 岗位图谱","description":"理解芯片设计、验证、制造和工具研发岗位的职责、技能栈及面试准备方向。","frontmatter":{"title":"IC 岗位图谱","description":"理解芯片设计、验证、制造和工具研发岗位的职责、技能栈及面试准备方向。"},"headers":[],"relativePath":"career/employment/index.md","filePath":"career/employment/index.md","lastUpdated":1795531638000}'),i={name:"career/employment/index.md"};function o(h,t,n,s,c,l){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="ic-岗位图谱" tabindex="-1">IC 岗位图谱 <a class="header-anchor" href="#ic-岗位图谱" aria-label="Permalink to &quot;IC 岗位图谱&quot;">​</a></h1><p>“做芯片”包含许多不同工作。岗位名在企业间并不统一，前端、架构、验证、实现和软件也可能交叉。选择岗位时先读实际职责、交付物和协作关系，再看工具列表；会打开软件不等于掌握工程方法。</p><h2 id="设计与实现岗位" tabindex="-1">设计与实现岗位 <a class="header-anchor" href="#设计与实现岗位" aria-label="Permalink to &quot;设计与实现岗位&quot;">​</a></h2><table tabindex="0"><thead><tr><th>岗位</th><th>常见工作与技能栈</th><th>面试常见问题方向</th></tr></thead><tbody><tr><td>数字前端设计</td><td>微架构、RTL、逻辑综合；Verilog / SystemVerilog、时序逻辑、脚本</td><td>状态机、流水线、握手、时钟域跨越、复位、可综合性；为什么这样设计？</td></tr><tr><td>数字验证</td><td>制定验证计划、搭建环境、回归与覆盖率；SystemVerilog、UVM、断言、参考模型</td><td>激励与检查如何闭环、随机约束、功能覆盖与代码覆盖、定位失败的方法</td></tr><tr><td>可测性设计（DFT）</td><td>扫描链、自动测试向量生成、存储器自测试；测试原理与时序约束</td><td>故障模型、覆盖率、可控可观测性、扫描时钟与测试开销</td></tr><tr><td>数字后端 / 物理设计</td><td>布图、布局、时钟树、布线与签核；Tcl、静态时序分析、物理约束</td><td>setup / hold、时钟偏斜、拥塞、压降、工艺角、时序与功耗面积取舍</td></tr><tr><td>模拟 / 混合信号设计</td><td>放大器、数据转换、时钟与电源等；器件物理、反馈、噪声、SPICE</td><td>偏置、小信号、稳定性、噪声与失配、PVT、指标之间的权衡</td></tr><tr><td>模拟 / 定制版图</td><td>匹配、寄生、电源和可靠性；布局规则、DRC、LVS、寄生提取</td><td>共心与对称、护环、寄生反馈、天线效应、设计与版图如何协同</td></tr><tr><td>芯片架构 / 系统架构</td><td>需求建模、性能与带宽预算、软硬件划分；体系结构、工作负载、建模工具</td><td>瓶颈定位、性能模型、存储层次、互连、如何证明架构收益能落地</td></tr></tbody></table><p>前端工程师也要理解时序和物理限制，验证工程师也要理解设计意图，后端工程师也需要读懂约束来源。不要把岗位分工误解为知识可以完全割裂。</p><h2 id="器件、制造与生态岗位" tabindex="-1">器件、制造与生态岗位 <a class="header-anchor" href="#器件、制造与生态岗位" aria-label="Permalink to &quot;器件、制造与生态岗位&quot;">​</a></h2><table tabindex="0"><thead><tr><th>岗位</th><th>常见工作与技能栈</th><th>面试常见问题方向</th></tr></thead><tbody><tr><td>器件研发 / 建模</td><td>器件结构、表征、紧凑模型或 TCAD；半导体物理、数值分析、实验</td><td>能带、载流子、短沟道效应、参数提取、模型与测量偏差</td></tr><tr><td>工艺研发 / 工艺整合</td><td>单步工艺与流程集成、良率和可靠性；材料、工艺、统计与实验设计</td><td>光刻 / 刻蚀 / 沉积基本原理、过程窗口、缺陷、如何设计对照实验</td></tr><tr><td>封装 / 测试</td><td>封装互连、热与可靠性、量产测试；电学测量、测试脚本、统计</td><td>信号完整性、热管理、测试覆盖、良率、量测重复性和异常定位</td></tr><tr><td>现场应用工程师（FAE）</td><td>客户方案支持、调试与技术沟通；器件或系统应用、仪器、文档</td><td>如何复现客户问题、区分器件与系统原因、解释规格并推进解决</td></tr><tr><td>EDA 研发</td><td>综合、布局布线、仿真、验证或分析工具；C++、数据结构、图算法、优化、数值方法</td><td>算法正确性与复杂度、内存与性能、约束建模、基准公平性、回归测试</td></tr></tbody></table><p>EDA 应用工程师与 EDA 研发工程师的侧重点不同：前者更关注工具部署、流程、客户设计与问题定位，后者通常更强调算法及软件实现。IP 企业也可能同时招聘设计、验证、物理实现与应用支持岗位。</p><h2 id="把课程项目转成岗位证据" tabindex="-1">把课程项目转成岗位证据 <a class="header-anchor" href="#把课程项目转成岗位证据" aria-label="Permalink to &quot;把课程项目转成岗位证据&quot;">​</a></h2><p>选择一到两个项目做深，而不是为每个岗位快速拼一个演示。至少保留：需求说明、结构图、个人贡献、测试计划、失败案例、结果与复现步骤。数字设计可沿<a href="/shanghaitech-ic-wiki-dev.github.io/learning/digital-ic/resources">数字路线</a>深入，模拟和器件分别参考<a href="/shanghaitech-ic-wiki-dev.github.io/learning/analog-ic/resources">模拟路线</a>与<a href="/shanghaitech-ic-wiki-dev.github.io/learning/devices-and-process/resources">器件路线</a>，EDA 参考<a href="/shanghaitech-ic-wiki-dev.github.io/learning/eda/resources">算法路线</a>。</p><p>面试准备可以按三层展开：</p><ol><li><strong>基础</strong>：不用工具也能解释核心概念，画出电路、时序或数据流。</li><li><strong>项目</strong>：解释设计取舍、个人工作、验证范围与最困难的问题。</li><li><strong>工程</strong>：讨论可维护性、异常输入、资源限制、协作和交付，而不是只谈最佳指标。</li></ol><p>没有用过某款商业工具，可以诚实说明学过的等价流程与可迁移知识，不声称“熟练掌握”。不会的问题，先说明条件再推理；背诵术语并不能替代理解。</p><h2 id="比较-offer-时看什么" tabindex="-1">比较 offer 时看什么 <a class="header-anchor" href="#比较-offer-时看什么" aria-label="Permalink to &quot;比较 offer 时看什么&quot;">​</a></h2><p>看具体团队与业务、培养与反馈机制、岗位内容、地点、劳动合同、保密与竞业条款，以及书面确定的薪酬结构。<strong>薪资以当年为准</strong>，不根据单个传闻给岗位或企业排名；不同学历、城市、团队与招聘批次不能直接横向比较。</p><p>企业地图见<a href="/shanghaitech-ic-wiki-dev.github.io/career/employment/companies">上海 IC 企业</a>，投递准备见<a href="/shanghaitech-ic-wiki-dev.github.io/career/internship/">实习指南</a>。职业发展可以跨岗位，但转向通常需要补齐对应的作品和工程知识，不是只改简历标题。</p><div class="info custom-block"><p class="custom-block-title">征集</p><p>欢迎通过<a href="/shanghaitech-ic-wiki-dev.github.io/community/contributing">参与共建</a>补充不同岗位的真实工作内容与准备经验，注明年份和岗位范围，不涉及薪资排名、雇主保密信息或对个人的评价。</p></div>',17)])])}const u=e(i,[["render",o]]);export{g as __pageData,u as default};
